// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/integer_overflow_1.sol";

contract OverflowTest is Test {
    Overflow public overflowContract;
    address attacker = address(0x1337);
    address victim = address(0x999);

    function setUp() public {
        overflowContract = new Overflow();
        vm.deal(attacker, 1 ether);
        vm.deal(victim, 1 ether);
    }

    function testOverflowProtection() public {
        // Initial deposit by victim
        vm.prank(victim);
        overflowContract.add(100);

        // Attacker deposits a small amount
        vm.prank(attacker);
        overflowContract.add(1);

        // Check initial balances
        assertEq(overflowContract.userBalances(attacker), 1);
        assertEq(overflowContract.userBalances(victim), 100);

        // Attempt to withdraw more than balance should revert
        vm.prank(attacker);
        vm.expectRevert();
        overflowContract.withdraw(2); // Should revert due to overflow protection
    }

    function testUncheckedOverflow() public {
        // Test that the unchecked block in add() function allows overflow
        // We'll simulate overflow by setting a high initial balance

        // First deposit to set initial state (just below overflow threshold)
        uint256 largeAmount = type(uint256).max / 2;
        vm.prank(attacker);
        overflowContract.add(largeAmount);

        // Second deposit that should cause overflow in sellerBalance (unchecked)
        vm.prank(attacker);
        overflowContract.add(largeAmount); // This should overflow sellerBalance

        // Verify user balance was updated correctly (shouldn't overflow)
        assertEq(overflowContract.userBalances(attacker), largeAmount * 2);
    }

    function testNormalOperation() public {
        // Test normal operation without overflow
        uint256 depositAmount = 100;

        vm.prank(victim);
        overflowContract.add(depositAmount);

        assertEq(overflowContract.userBalances(victim), depositAmount);
    }

    function testMaximumDeposit() public {
        // Test depositing maximum possible value
        uint256 maxAmount = type(uint256).max;

        vm.prank(attacker);
        overflowContract.add(maxAmount);

        assertEq(overflowContract.userBalances(attacker), maxAmount);

        // Attempt to deposit more should revert
        vm.prank(attacker);
        vm.expectRevert();
        overflowContract.add(1);
    }
}
